/**
 * Human-friendly claim codes for instance setup
 *
 * A claim code lets the admin bootstrap an instance.  Format is
 * ADJECTIVE-NOUN-4digits, e.g. QUIET-HERON-4471, and it normalises to uppercase
 * with no spaces
 *
 * Not generated by random-readable words: the adjective/noun pairs are fixed
 * lists, and the digits are the only entropy.  That is intentional to keep
 * collision checking simple in the caller
 */

import { randomInt } from 'node:crypto';

const ADJECTIVES = [
  'AMBER',
  'BRIGHT',
  'CALM',
  'CLEAR',
  'COPPER',
  'CRISP',
  'DEEP',
  'EAGER',
  'EVEN',
  'FIRM',
  'GENTLE',
  'GLAD',
  'GOLDEN',
  'GRAND',
  'GREEN',
  'HOLLOW',
  'IRON',
  'IVORY',
  'KEEN',
  'LEVEL',
  'LIVELY',
  'LOYAL',
  'MELLOW',
  'MILD',
  'NIMBLE',
  'NOBLE',
  'OPEN',
  'PLAIN',
  'PROMPT',
  'QUIET',
  'RAPID',
  'READY',
  'ROUND',
  'SILVER',
  'SMOOTH',
  'SOLID',
  'STEADY',
  'STILL',
  'SUNNY',
  'SWIFT',
  'TIDY',
  'TRUE',
  'VIVID',
  'WARM',
  'WHOLE',
  'WILLING',
  'WISE',
  'YOUNG',
];

const NOUNS = [
  'ANCHOR',
  'BADGER',
  'BEACON',
  'BIRCH',
  'BRIDGE',
  'CANYON',
  'CEDAR',
  'COMPASS',
  'CORAL',
  'DELTA',
  'FALCON',
  'FERRY',
  'GARDEN',
  'HARBOUR',
  'HERON',
  'ISLAND',
  'JUNIPER',
  'KETTLE',
  'LANTERN',
  'LEDGER',
  'MARBLE',
  'MEADOW',
  'MERIDIAN',
  'ORCHARD',
  'OTTER',
  'PLATEAU',
  'QUARRY',
  'RIVER',
  'SADDLE',
  'SIGNAL',
  'SPARROW',
  'STATION',
  'SUMMIT',
  'TERRACE',
  'THICKET',
  'TIMBER',
  'VALLEY',
  'VESSEL',
  'WALNUT',
  'WILLOW',
  'WINDOW',
  'YARROW',
];

export function mintClaimCode(): string {
  const adjective = ADJECTIVES[randomInt(ADJECTIVES.length)];
  const noun = NOUNS[randomInt(NOUNS.length)];
  const digits = String(randomInt(1000, 10000));
  return `${adjective}-${noun}-${digits}`;
}

export function normalizeClaimCode(raw: string): string | null {
  const code = raw.trim().toUpperCase().replace(/\s+/g, '');
  return CODE_SHAPE.test(code) ? code : null;
}

/** Matches ADJECTIVE-NOUN-4digits after normalisation */
export const CODE_SHAPE = /^[A-Z]{3,10}-[A-Z]{3,10}-[0-9]{4}$/;
